using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Measurement.Pgm;
internal sealed class EquiprobablePgmCommutingDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Measurement/Pgm/EquiprobablePgmCommuting.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Universal actual-object PGM control", H("EquiprobablePgmCommuting"), Blocks(
            Node("every_optimum", "Every actual optimum on the five-dimensional support",
                "For every 0<epsilon<7/18, the first four states have populations (1-epsilon)e0+epsilon e_i, i=1..4, and the fifth (1-2epsilon)e0+(epsilon/2)sum_(i=1..4)e_i. These actual diagonal trace-one PSD matrices commute. An actual POVM attains (1+3epsilon)/5. Every optimal complex POVM, including competitors with off-diagonal entries, has this score and precisely the first four nonzero effects. Complementary products with the diagonal dual slack force the fifth effect to vanish and each rare coordinate to be assigned to its unique maximizing label. This theorem is on the complete five-dimensional joint support."),
            Node("scores_and_gap", "The complete commuting interval and exact CFC scores",
                "On every 0<epsilon<7/18, actual P_A=(1+3epsilon)/5=P_opt and P_all=1/5+32epsilon/75+4epsilon^2/[25(5-6epsilon)]. For centered eta_A=P_A-1/5 and eta=P_all-1/5 the exact gap is 3eta_A-4eta=epsilon(7-18epsilon)/[15(5-6epsilon)]>0. The endpoints are excluded. The diagonal Moore-Penrose score theorem evaluates actual CFC objects, including the zeros in individual states."),
            Node("nonunique", "Nonuniqueness of the optimal measurement",
                "For every epsilon>0 the displayed score optimization has two distinct actual optimal finitePOVMs, obtained by allocating the common coordinate wholly to two different first-four labels. On the physical interval they are optimal discrimination POVMs for the stated density ensemble. The common-coordinate tie explains nonuniqueness. No every-optimum activity claim is made about effects living entirely in an unused ambient kernel."),
            Node("population", "Complete commuting populations", "On coordinates 0..4, first-four labels i=0..3 use (1-epsilon)e0+epsilon e_(i+1); label4 uses (1-2epsilon)e0+(epsilon/2)sum_(j=1..4)e_j.", DescribeRole.Definition),
            Node("states", "Actual commuting density matrices", "Each actual state is the complex diagonal matrix of population. Individual first-four states have rank two; the physical domain is 0<epsilon<7/18.", DescribeRole.Definition),
            Node("effects", "Actual tied-coordinate POVMs", "Each first-four label receives its rare coordinate; nonnegative weights summing to one allocate the common coordinate among labels. For the stated optimum construction the fifth common weight vanishes.", DescribeRole.Definition),
            Node("centered_ratio_limit", "Actual centered ratio at the commuting endpoint", "As epsilon decreases to zero, the ratio of the actual full advantage to the actual pair-set advantage tends to 32/45, which is strictly below 3/4. The exact interval scores determine the continuous ratio 32/45+4epsilon/[15(5-6epsilon)].", DescribeRole.Theorem),
            Node("selected_ranks", "Actual selected states have rank two", "For every 0<epsilon<7/18, all first-four actual density matrices have matrix rank exactly two. They are not PD in dimension five.", DescribeRole.Theorem),
            Node("joint_support", "The actual joint support is dimension five", "For every physical epsilon, spectralSupport of the actual full average equals the identity on Fin5. The individual states may be singular; the average has full five-dimensional support.", DescribeRole.Theorem),
            Node("supportInclusion", "Fixed support inclusion into dimension eight", "The actual coordinate isometry includes the five support coordinates into Fin8. It introduces three unused ambient kernel coordinates.", DescribeRole.Definition),
            Node("embeddedStates", "Actual dimension-eight embedded states", "Embedded states are V rho_i V-adjoint for the fixed coordinate isometry V. They are actual PSD trace-one matrices with the original five-dimensional joint support.", DescribeRole.Definition),
            Node("dimension_eight_optima", "Every ambient optimum after support compression", "Throughout 0<epsilon<7/18, an actual optimal dimension-eight finitePOVM exists. Every complex ambient optimum scores (1+3epsilon)/5 and its compression to the five-dimensional joint support has exactly active labels {0,1,2,3}. Every support POVM can be lifted by assigning the unused kernel to label0. No claim is made that every ambient completion has the same uncompressed nonzero labels.", DescribeRole.Theorem),
            Node("dimension_eight_support_and_scores", "Embedded support, ranks and actual CFC scores", "For every physical epsilon the actual full-average spectral support is diag(1,1,1,1,1,0,0,0); the first-four embedded states have rank two. Actual restricted score is (1+3epsilon)/5 and full score is 1/5+32epsilon/75+4epsilon^2/[25(5-6epsilon)]. CFC uses Moore-Penrose zero action on the three-dimensional kernel.", DescribeRole.Theorem),
            Paragraph(Text("The construction and symmetric calculations are credited to Hyunho Cha. Mechanism attribution remains anonymous; old literal byline Wenlin Zhang and Haobo / trureturing; new note Haobo Ma then Wenlin Zhang. CC BY 4.0 applies to the new note only. The original nonzero-effect interpretation of activity is retained, including rank-one effects; the source wording about positive definite effects is ambiguous. General all-pure and positive-spectral-floor comparisons remain open."))
        ), []));
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create("equiprobablepgmcommuting-" + name.Replace('_', '-').ToLowerInvariant()),
        DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
        AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Estimation/anonymous2026pgmmechanism")),
        Blocks(Paragraph(Text(prose))), role);
